/*
 * A298231  Fixed point of the morphism 1->1221, 2->122.
 * https://oeis.org/A298231
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 250, u16 n <= 250, u32 n <= 250, u64 n <= 250,
 *            u128 n <= 250, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Fixed point of the morphism 1->1221, 2->122 (OEIS A298231) */
/* The sequence is generated by successive application of the morphism
 * starting from the word "1".  The function keeps a static cache of the
 * word as it grows and returns the n-th symbol (n ≥ 1). */

#include <stdlib.h>

/* The function signature required by the build system */
seq_t a(idx_t n)
{
    static seq_t *seq = NULL;   /* cache of the generated word */
    static size_t seq_len = 0;  /* current length of seq          */

    /* Ensure that the cache is initialised with the first symbol. */
    if (seq_len == 0)
    {
        seq = (seq_t *)malloc(sizeof(seq_t));
        if (seq == NULL) return 0;          /* out of memory – unlikely here */
        seq[0] = (seq_t)1;
        seq_len = 1;
    }

    /* Grow the cache until it contains the n-th symbol. */
    while (seq_len < (size_t)n)
    {
        /* Count how many 1's and 2's are currently in the word. */
        size_t cnt1 = 0, cnt2 = 0;
        for (size_t i = 0; i < seq_len; ++i)
        {
            if (seq[i] == (seq_t)1) ++cnt1;
            else                    ++cnt2;   /* only 2 may appear */
        }

        /* Length of the next word after applying the morphism. */
        size_t new_len = 4 * cnt1 + 3 * cnt2;

        /* Allocate new word. */
        seq_t *new_seq = (seq_t *)malloc(new_len * sizeof(seq_t));
        if (new_seq == NULL) return 0;        /* out of memory */

        /* Build the new word by replacing every symbol according to
         * the morphism: 1 -> 1 2 2 1,  2 -> 1 2 2. */
        size_t pos = 0;
        for (size_t i = 0; i < seq_len; ++i)
        {
            if (seq[i] == (seq_t)1)
            {
                new_seq[pos++] = (seq_t)1;
                new_seq[pos++] = (seq_t)2;
                new_seq[pos++] = (seq_t)2;
                new_seq[pos++] = (seq_t)1;
            }
            else /* seq[i] == 2 */
            {
                new_seq[pos++] = (seq_t)1;
                new_seq[pos++] = (seq_t)2;
                new_seq[pos++] = (seq_t)2;
            }
        }

        /* Replace the old cache. */
        free(seq);
        seq = new_seq;
        seq_len = new_len;
    }

    /* Return the desired symbol (n is 1‑based). */
    return seq[(size_t)(n - 1)];
}
